<script setup lang="ts">
import {confirmAction} from '../lib/dialog';
import {ref,computed,watch,onMounted} from 'vue';import EventPicker from '../components/EventPicker.vue';import {api,catalog,loadCatalog,displayTime} from '../lib/api';import type {Wish,WishList} from '../../shared/wishes';
const items=ref<Wish[]>([]),total=ref(0),page=ref(1),search=ref(''),loading=ref(false),error=ref(''),notice=ref(''),exporting=ref(false),selected=ref<string[]>([]),ready=ref(false),scope=ref<'selected'|'filtered'|'all'>('filtered'),appliedSearch=ref('');const scopeText=computed(()=>scope.value==='selected'?'已选 '+selected.value.length+' 份':scope.value==='filtered'?'当前筛选结果（'+total.value+' 份）':'本活动全部');let sequence=0;
async function load(){const current=++sequence,eventId=catalog.eventId,term=search.value.trim();if(!eventId)return;loading.value=true;error.value='';try{const data=await api<WishList>('/api/admin/wishes?'+new URLSearchParams({event_id:eventId,page:String(page.value),search:term}));if(current!==sequence)return;items.value=data.items;total.value=data.total;ready.value=data.audio_ready;appliedSearch.value=term;selected.value=[];}catch(e){if(current===sequence)error.value=(e as Error).message;}finally{if(current===sequence)loading.value=false;}}
function selectPage(e:Event){selected.value=(e.target as HTMLInputElement).checked?items.value.map(w=>w.id):[];scope.value='selected';}
function exportHref(kind:'text'|'audio'){return '/api/admin/wishes/export?'+new URLSearchParams({event_id:catalog.eventId,kind,...(scope.value==='selected'?{ids:selected.value.join(',')}:scope.value==='filtered'?{search:appliedSearch.value}:{})});}
async function pack(kind:'text'|'audio'){if(scope.value==='selected'&&!selected.value.length){error.value='请先勾选需要下载的祝福语。';return;}exporting.value=true;error.value='';notice.value='';try{const path=exportHref(kind);const check=await api<{count:number;size:number}>(path.replace('/export?','/export-check?'));if(!await confirmAction(`将下载${kind==='text'?'文本':'音频'} ${check.count} 份（${scopeText.value}）${kind==='audio'?'，约 '+(check.size/1000000).toFixed(1)+' MB':''}，是否开始？`))return;const a=document.createElement('a');a.href=path;a.download=kind==='text'?'祝福语文本.zip':'祝福语音频.zip';a.click();notice.value='打包下载已开始，请查看浏览器的下载列表。';}catch(e){error.value=(e as Error).message;}finally{exporting.value=false;}}
watch(()=>catalog.eventId,()=>{page.value=1;void load();});watch(page,()=>void load());onMounted(async()=>{try{if(!catalog.config)await loadCatalog();await load();}catch(e){error.value=(e as Error).message;}});
</script>
<template><div class="page"><header class="page-head"><div><h1>祝福语管理</h1></div><EventPicker/></header><p v-if="error" class="alert error" role="alert">{{ error }}</p><p v-if="notice" class="alert success" role="status">{{ notice }}</p><section class="paper wish-tools"><form class="inline" @submit.prevent="page=1;load()"><label class="grow">搜索署名或祝福语<input v-model="search" maxlength="100" placeholder="输入关键词"></label><button :disabled="loading">搜索</button><RouterLink to="/wishes" class="button primary">投稿祝福语</RouterLink></form><div class="export-bar"><label>下载范围<select v-model="scope"><option value="filtered">当前筛选结果</option><option value="selected">本页已选内容</option><option value="all">本活动全部</option></select></label><label class="check"><input type="checkbox" :checked="!!items.length&&selected.length===items.length" :disabled="loading||!items.length" @change="selectPage">选择本页</label><span class="hint">本页已选 {{ selected.length }} 份，翻页会清空选择。</span><button :disabled="loading||exporting||(scope==='selected'&&!selected.length)" @click="pack('text')">{{ exporting?'准备打包…':'下载文本 · '+scopeText }}</button><button :disabled="loading||!ready||exporting||(scope==='selected'&&!selected.length)" @click="pack('audio')">下载音频 · {{ scopeText }}</button></div><p class="hint">文本包内每份祝福语为一个 TXT 文件。音频保留原格式；单次最多 100 份、合计 1 GB，较多时可勾选后分批下载。</p><p v-if="!ready" class="hint">语音存储暂未开通，文本查看与导出可正常使用。</p></section><section class="paper wish-results"><div class="inline"><h2>已提交的祝福语</h2><span class="hint">共 {{ total }} 份</span></div><p v-if="loading" role="status" class="empty">正在读取祝福语…</p><p v-else-if="!items.length" class="empty">还没有符合条件的祝福语。</p><article v-for="wish in items" :key="wish.id" class="wish-row"><label class="check wish-select"><input v-model="selected" @change="scope='selected'" type="checkbox" :value="wish.id" :aria-label="'选择 '+wish.display_name+' 的祝福语'"></label><div class="wish-body"><header class="inline"><h3>{{ wish.display_name }}</h3><span class="hint">{{ displayTime(wish.submitted_at,catalog.events.find(e=>e.id===catalog.eventId)?.timezone) }}</span></header><p class="prewrap">{{ wish.text||'（未填写祝福语文本）' }}</p><div v-if="wish.filename" class="audio-row"><audio controls preload="none" :src="'/api/wishes/'+wish.id+'/audio'" :aria-label="wish.display_name+'的祝福语音'"></audio><a :href="'/api/wishes/'+wish.id+'/audio?download=1'" class="button" download>下载音频</a><small class="hint">{{ wish.filename }} · {{ ((wish.size??0)/1024/1024).toFixed(2) }} MB</small></div><span v-else class="hint">文本祝福</span></div></article><div class="pagination"><button :disabled="page===1||loading" @click="page--">上一页</button><span>{{ page }}</span><button :disabled="page*30>=total||loading" @click="page++">下一页</button></div></section></div></template>
<style scoped>
.wish-tools label.grow{margin:0}.export-bar{display:flex;align-items:center;gap:16px;flex-wrap:wrap;border-top:1px solid var(--line);padding-top:20px;margin-top:20px}.export-bar label{margin:0}.export-bar a[aria-disabled=true]{opacity:.45;cursor:default}.wish-results h2{font-size:22px}.wish-row{display:flex;gap:18px;padding:24px 0;border-bottom:1px solid var(--line)}.wish-select{align-self:flex-start;padding-top:4px}.wish-body{min-width:0;flex:1}.wish-body h3{margin:0;font-size:18px}.wish-body header{justify-content:space-between}.prewrap{overflow-wrap:anywhere}.audio-row{display:flex;gap:12px;align-items:center;flex-wrap:wrap}audio{max-width:100%;width:340px}.button{display:inline-flex;align-items:center;justify-content:center;min-height:44px;border:1px solid var(--line);border-radius:8px;padding:10px 16px;background:var(--paper)}.button.primary{background:var(--plum);color:white}@media(max-width:760px){.wish-tools .inline{align-items:stretch;flex-wrap:wrap}.wish-tools label.grow{width:100%;flex-basis:100%}.wish-body header{align-items:flex-start;gap:8px}.wish-row{gap:10px}.audio-row{display:block}.audio-row a{margin:8px 0}.audio-row small{display:block}}
</style>
